if($_SERVER['REQUEST_METHOD']==='POST'&&logged()&&in_array($_POST['action']??'', ['trash_student','restore_student','purge_student'],true)){
    checkcsrf();
    try{
        $studentId=(int)($_POST['student_id']??0);
        if($studentId<1)throw new RuntimeException('Choose a valid student record.');
        if($_POST['action']==='trash_student'){
            $statement=$pdo->prepare('UPDATE students SET trashed_status=status,status=\'Deleted\',deleted_at=CURRENT_TIMESTAMP,purge_after=datetime(\'now\',\'+90 days\') WHERE id=? AND deleted_at IS NULL');
            $statement->execute([$studentId]);
            if($statement->rowCount()!==1)throw new RuntimeException('That student record is unavailable or already in trash.');
            logaction($pdo,'Move student to trash','Student ID '.$studentId.'; retained for 90 days');
        }elseif($_POST['action']==='restore_student'){
            $statement=$pdo->prepare('UPDATE students SET status=COALESCE(trashed_status,\'Active\'),trashed_status=NULL,deleted_at=NULL,purge_after=NULL WHERE id=? AND deleted_at IS NOT NULL AND purge_after>CURRENT_TIMESTAMP');
            $statement->execute([$studentId]);
            if($statement->rowCount()!==1)throw new RuntimeException('That student record is no longer available to restore.');
            logaction($pdo,'Restore student from trash','Student ID '.$studentId);
        }else{
            $studentQuery=$pdo->prepare('SELECT photo FROM students WHERE id=? AND deleted_at IS NOT NULL');
            $studentQuery->execute([$studentId]);
            $photo=$studentQuery->fetchColumn();
            if($photo===false)throw new RuntimeException('Only records in trash can be permanently deleted.');
            $pdo->beginTransaction();
            try{
                foreach(['marks','comments','enrollments'] as $table){
                    $statement=$pdo->prepare("DELETE FROM {$table} WHERE student_id=?");
                    $statement->execute([$studentId]);
                }
                $statement=$pdo->prepare('DELETE FROM students WHERE id=? AND deleted_at IS NOT NULL');
                $statement->execute([$studentId]);
                if($statement->rowCount()!==1)throw new RuntimeException('The student record could not be permanently deleted.');
                logaction($pdo,'Permanently delete student','Student ID '.$studentId.' and associated marks, comments, and enrolments');
                $pdo->commit();
            }catch(Throwable $error){
                if($pdo->inTransaction())$pdo->rollBack();
                throw $error;
            }
            if(is_string($photo)&&preg_match('~^uploads/[a-f0-9]{24}\.(?:jpg|png|webp)$~',$photo)&&is_file(__DIR__.'/'.$photo)&&!unlink(__DIR__.'/'.$photo)){
                error_log('Could not remove permanently deleted student photo: '.$photo);
            }
        }
        go('index.php?page=student_trash&updated=1');
    }catch(Throwable $error){
        $errorMessage=$error instanceof PDOException?'Could not update the student record. Please try again.':$error->getMessage();
        $_SESSION['student_trash_error']=$errorMessage;
        go('index.php?page=student_trash');
    }
}
