}.report{background:white;max-width:780px;margin:20px auto;box-shadow:0 8px 30px #0002}}</style></head><body><div class="print-actions no-print"><button class="btn" onclick="window.print()">Print <?= $isBatch?'all '.count($pupils).' class reports':'this report' ?></button> <button class="btn secondary" onclick="history.back()">Back</button><span> Use A4 paper, portrait orientation.</span></div><?php foreach($pupils as $p):$mq=$pdo->prepare('SELECT su.name,m.score,m.teacher_comment FROM subjects su LEFT JOIN marks m ON m.subject_id=su.id AND m.student_id=? AND m.academic_year=? AND m.term=? AND m.assessment="EOT" WHERE (su.stage="all" OR (su.stage="lower" AND ?<=3) OR (su.stage="upper" AND ?>3)) ORDER BY su.id');$mq->execute([$p['id'],$year,$term,$p['level'],$p['level']]);$rows=$mq->fetchAll();$total=0;$count=0;?><article class="report"><div class="report-head"><img src="assets/school-logo.jpg"><div><h1><?= h($set['school_name']??$school) ?></h1><p><?= h($set['address']??'') ?></p><p><?= h($set['phone']??'') ?> | <?= h($set['email']??'') ?></p></div></div><div class="report-title">TERMINAL REPORT — <?= h($year) ?> TERM <?= h(['','ONE','TWO','THREE'][$term]??$term) ?></div><div class="identity"><div><b>NAME:</b> <?= h($p['full_name']) ?></div><div><b>CLASS:</b> <?= h($p['class_name']) ?></div><div><b>ADMISSION NO:</b> <?= h($p['admission_no']) ?></div><div><b>TERM:</b> <?= h(['','ONE','TWO','THREE'][$term]??$term) ?></div></div><table><thead><tr><th>SUBJECT</th><th>MARKS / 100</th><th>GRADE</th><th>TEACHER REMARKS</th></tr></thead><tbody><?php foreach($rows as $r):$sc=$r['score'];if($sc!==null){$total+=(float)$sc;$count++;}$grade=$sc===null?'—':($sc>=90?'A':($sc>=80?'B':($sc>=60?'C':($sc>=50?'D':'E'))));?><tr><td><?= h($r['name']) ?></td><td><?= $sc===null?'—':h(number_format((float)$sc,0)) ?></td><td><?= h($grade) ?></td><td><?= h($r['teacher_comment']?:'') ?></td></tr><?php endforeach;?><tr><th>TOTAL / <?= count($rows)*100 ?></th><th><?= $count?number_format($total,0):'—' ?></th><th colspan="2">AVERAGE: <?= $count?number_format($total/$count,1).'%':'—' ?></th></tr></tbody></table><?php $cq=$pdo->prepare('SELECT * FROM comments WHERE student_id=? AND academic_year=? AND term=?');$cq->execute([$p['id'],$year,$term]);$co=$cq->fetch()?:[];?><div class="comment"><b>Class Teacher's Comments</b><p><?= h($co['class_comment']??'') ?></p><div class="signatures"><span>Class Teacher</span><span>Signature: __________________</span></div></div><div class="comment"><b>Head Teacher's Comments</b><p><?= h($co['head_comment']??'') ?></p><div class="signatures"><span>Head Teacher</span><span>Signature: __________________</span></div></div><div class="comment"><b>School Requirements / Next Term</b><p><?= h($set['next_term']??'') ?></p></div><div class="motto"><?= h($set['motto']??'') ?></div></article><?php endforeach;?></body></html><?php exit;}
