<?php elseif($page==='profile'):$id=(int)($_GET['id']??0);$q=$pdo->prepare('SELECT s.*,c.name class_name,c.level FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?');$q->execute([$id]);$s=$q->fetch();if(!$s):?><div class="alert error">Student record not found.</div><?php else:$history=$pdo->prepare('SELECT e.*,c.name class_name FROM enrollments e JOIN classes c ON c.id=e.class_id WHERE e.student_id=? ORDER BY e.academic_year DESC,e.id DESC');$history->execute([$id]);$hist=$history->fetchAll();?><div class="page-intro"><div><div class="eyebrow">LEARNER PROFILE</div><h1>Student profile</h1><p>Personal details and academic history in one place.</p></div><div class="action-row"><a class="btn secondary" href="index.php?page=marks&student=<?= $id ?>">Enter marks</a><a class="btn" href="index.php?page=student_form&id=<?= $id ?>">Edit profile</a></div></div><section class="profile-hero panel"><div class="profile-photo"><?php if($s['photo']&&file_exists(__DIR__.'/'.$s['photo'])):?><img src="<?= h($s['photo']) ?>" alt="Student photograph"><?php else:?><span><?= h(strtoupper(substr($s['full_name'],0,1))) ?></span><?php endif;?></div><div class="profile-main"><span class="class-pill"><?= h($s['class_name']) ?></span><h2><?= h($s['full_name']) ?></h2><p><?= h($s['admission_no']) ?> · <?= h($s['gender']) ?></p><span class="status <?= strtolower($s['status']) ?>"><?= h($s['status']) ?></span></div><div class="profile-actions"><a class="btn secondary" href="index.php?page=print&student=<?= $id ?>&year=<?= $year ?>&term=<?= $term ?>" target="_blank">Print report</a></div></section><div class="profile-grid"><section class="panel"><div class="panel-head"><div><h3>Personal details</h3><p>Student information</p></div></div><dl class="detail-list"><div><dt>Date of birth</dt><dd><?= h($s['dob']?:'Not provided') ?></dd></div><div><dt>Admission date</dt><dd><?= h($s['admission_date']?:'Not provided') ?></dd></div><div><dt>Parent / guardian</dt><dd><?= h($s['parent_name']?:'Not provided') ?></dd></div><div><dt>Parent phone</dt><dd><?= h($s['parent_phone']?:'Not provided') ?></dd></div><div><dt>Home address</dt><dd><?= h($s['address']?:'Not provided') ?></dd></div></dl></section><section class="panel"><div class="panel-head"><div><h3>Class history</h3><p>Previous and current enrolments</p></div></div><?php if(!$hist):?><p class="empty">No history has been recorded yet.</p><?php else:?><div class="history-list"><?php foreach($hist as $en):?><div class="history-item"><span class="history-dot"></span><div><b><?= h($en['class_name']) ?></b><small>Academic year <?= h($en['academic_year']) ?></small><p><?= h($en['note']) ?></p></div></div><?php endforeach;?></div><?php endif;?></section></div><?php endif;?>
<?php elseif($page==='marks'):$sid=(int)($_GET['student']??0);$student=null;if($sid){$q=$pdo->prepare('SELECT s.*,c.name class_name,c.level FROM students s JOIN classes c ON c.id=s.class_id WHERE s.id=?');$q->execute([$sid]);$student=$q->fetch();}if(!$student){$q=$pdo->prepare('SELECT s.*,c.name class_name,c.level FROM students s JOIN classes c ON c.id=s.class_id WHERE s.status="Active" ORDER BY s.full_name LIMIT 1');$q->execute();$student=$q->fetch();$sid=(int)($student['id']??0);}$subjects=$student?$pdo->prepare('SELECT * FROM subjects WHERE stage="all" OR (stage="lower" AND ?<=3) OR (stage="upper" AND ?>3) ORDER BY id'):null;if($subjects){$subjects->execute([$student['level'],$student['level']]);$subjects=$subjects->fetchAll();}$mq=$pdo->prepare('SELECT subject_id,score,teacher_comment FROM marks WHERE student_id=? AND academic_year=? AND term=? AND assessment="EOT"');$mq->execute([$sid,$year,$term]);$saved=[];foreach($mq as $r)$saved[$r['subject_id']]=$r;$cq=$pdo->prepare('SELECT * FROM comments WHERE student_id=? AND academic_year=? AND term=?');$cq->execute([$sid,$year,$term]);$co=$cq->fetch()?:[];?><div class="page-intro"><div><div class="eyebrow">ACADEMIC ASSESSMENT</div><h1>Marks entry</h1><p>Enter or update end-of-term marks for each subject.</p></div></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="marks"><label class="filter-label">Student<select name="student" onchange="this.form.submit()"><option value="0">Select student</option><?php $all=$pdo->query('SELECT s.id,s.full_name,c.name class_name FROM students s JOIN classes c ON c.id=s.class_id WHERE s.status="Active" ORDER BY c.level,s.full_name');foreach($all as $st):?><option value="<?= $st['id'] ?>" <?= $sid===$st['id']?'selected':'' ?>><?= h($st['class_name'].' — '.$st['full_name']) ?></option><?php endforeach;?></select></label><label class="filter-label">Year<input type="number" name="year" min="2020" max="2100" value="<?= $year ?>"></label><label class="filter-label">Term<select name="term"><?php for($t=1;$t<=3;$t++):?><option value="<?= $t ?>" <?= $term===$t?'selected':'' ?>>Term <?= $t ?></option><?php endfor;?></select></label><button class="btn" type="submit">Load records</button></form><?php if($student):?><form class="panel form-panel" method="post"><input type="hidden" name="csrf" value="<?= h(csrf()) ?>"><input type="hidden" name="action" value="save_marks"><input type="hidden" name="student_id" value="<?= $sid ?>"><input type="hidden" name="year" value="<?= $year ?>"><input type="hidden" name="term" value="<?= $term ?>"><input type="hidden" name="assessment" value="EOT"><div class="selected-student"><span class="student-avatar"><?= h(strtoupper(substr($student['full_name'],0,1))) ?></span><div><b><?= h($student['full_name']) ?></b><small><?= h($student['class_name'].' · '.$student['admission_no']) ?></small></div><span class="class-pill">Term <?= $term ?> · <?= $year ?></span></div><div class="table-wrap"><table class="marks-table"><thead><tr><th>Subject</th><th>Mark / 100</th><th>Current grade</th></tr></thead><tbody><?php foreach($subjects as $sub):$sc=$saved[$sub['id']]['score']??'';$gr=$sc===''?'—':($sc>=90?'A':($sc>=80?'B':($sc>=60?'C':($sc>=50?'D':'E'))));?><tr><td><b><?= h($sub['name']) ?></b></td><td><input class="score-input" type="number" min="0" max="100" step="1" name="score[<?= $sub['id'] ?>]" value="<?= h($sc) ?>" placeholder="—" data-grade="grade-<?= $sub['id'] ?>"></td><td><span class="grade-chip" id="grade-<?= $sub['id'] ?>"><?= h($gr) ?></span></td></tr><?php endforeach;?></tbody></table></div><div class="form-grid comment-grid"><label>Class teacher's comment<textarea name="class_comment" rows="3" placeholder="Progress, effort and areas to improve..."><?= h($co['class_comment']??'') ?></textarea></label><label>Head teacher's comment<textarea name="head_comment" rows="3" placeholder="Overall school comment..."><?= h($co['head_comment']??'') ?></textarea></label></div><div class="form-footer"><p>Grades use the configured demo scale: A 90–100, B 80–89, C 60–79, D 50–59, E 0–49. Confirm the school's official scale before real use.</p><button class="btn" type="submit">Save marks and comments</button></div></form><?php else:?><div class="alert">No active students are available. Register a student first.</div><?php endif;?>
<?php elseif($page==='reports'):?><div class="page-intro"><div><div class="eyebrow">PRINT CENTRE</div><h1>Report cards</h1><p>Choose one learner or a class to prepare print-ready A4 reports.</p></div></div><section class="report-feature"><div class="report-feature-image"><img src="assets/report-primary.jpg" alt="Primary report card example"></div><div class="report-feature-copy"><span class="eyebrow light">PRINT · REVIEW · SHARE</span><h2>One class.<br>All reports. One click.</h2><p>Generate reports for a whole class in one print job, or open a single pupil's report. Each report starts on a fresh page.</p><ul><li>A4 print-friendly layout</li><li>School identity and report period</li><li>Subject marks, grades and comments</li><li>Separate page for each pupil</li></ul></div></section><form class="panel report-picker" method="get" action="index.php" target="_blank"><input type="hidden" name="page" value="print"><div class="panel-head"><div><h3>Prepare class reports</h3><p>Select the class and academic period you want to print.</p></div></div><div class="form-grid"><label>Class<select name="class" required><?php foreach($classes as $c):?><option value="<?= $c['id'] ?>"><?= h($c['name']) ?></option><?php endforeach;?></select></label><label>Academic year<input type="number" name="year" min="2020" max="2100" value="<?= $year ?>" required></label><label>Term<select name="term"><?php for($t=1;$t<=3;$t++):?><option value="<?= $t ?>" <?= $term===$t?'selected':'' ?>>Term <?= $t ?></option><?php endfor;?></select></label></div><div class="form-footer"><p>Use your browser's print dialogue to select a printer or save as PDF.</p><button class="btn" type="submit">Open all class reports ↗</button></div></form><section class="panel"><div class="panel-head"><div><h3>Print one pupil's report</h3><p>Find a student and open their individual report.</p></div></div><form class="filter-bar" method="get" action="index.php" target="_blank"><input type="hidden" name="page" value="print"><label class="filter-label wide">Student<select name="student" required><?php foreach($pdo->query('SELECT s.id,s.full_name,s.admission_no,c.name class_name FROM students s JOIN classes c ON c.id=s.class_id ORDER BY c.level,s.full_name') as $st):?><option value="<?= $st['id'] ?>"><?= h($st['class_name'].' · '.$st['full_name'].' ('.$st['admission_no'].')') ?></option><?php endforeach;?></select></label><label class="filter-label">Year<input type="number" name="year" value="<?= $year ?>"></label><label class="filter-label">Term<select name="term"><?php for($t=1;$t<=3;$t++):?><option value="<?= $t ?>" <?= $term===$t?'selected':'' ?>>Term <?= $t ?></option><?php endfor;?></select></label><button class="btn" type="submit">Open report ↗</button></form></section>
<?php elseif($page==='performance'):$cid=(int)($_GET['class']??($classes[0]['id']??1));$q=$pdo->prepare('SELECT s.id,s.full_name,s.admission_no,c.name class_name,AVG(m.score) average,COUNT(m.id) subjects_count FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN marks m ON m.student_id=s.id AND m.academic_year=? AND m.term=? AND m.assessment="EOT" WHERE s.class_id=? AND s.status="Active" GROUP BY s.id ORDER BY average DESC,s.full_name');$q->execute([$year,$term,$cid]);$ranking=$q->fetchAll();?><div class="page-intro"><div><div class="eyebrow">LEARNER ACHIEVEMENT</div><h1>Class performance</h1><p>Review results and recognise the strongest performances in each class.</p></div></div><form class="filter-bar" method="get"><input type="hidden" name="page" value="performance"><label class="filter-label">Class<select name="class"><?php foreach($classes as $c):?><option value="<?= $c['id'] ?>" <?= $cid===$c['id']?'selected':'' ?>><?= h($c['name']) ?></option><?php endforeach;?></select></label><label class="filter-label">Year<input type="number" name="year" value="<?= $year ?>"></label><label class="filter-label">Term<select name="term"><?php for($t=1;$t<=3;$t++):?><option value="<?= $t ?>" <?= $term===$t?'selected':'' ?>>Term <?= $t ?></option><?php endfor;?></select></label><button class="btn">View performance</button></form><div class="winners-grid"><?php foreach(array_slice($ranking,0,3) as $i=>$r):?><article class="winner-card rank-<?= $i+1 ?>"><div class="winner-rank">0<?= $i+1 ?></div><div class="winner-avatar"><?= h(strtoupper(substr($r['full_name'],0,1))) ?></div><div class="eyebrow">TOP PERFORMER</div><h3><?= h($r['full_name']) ?></h3><p><?= h($r['class_name']) ?> · <?= h($r['admission_no']) ?></p><strong><?= $r['average']===null?'—':number_format((float)$r['average'],1).'%' ?></strong><span>Average mark</span><a class="inline-link" target="_blank" href="index.php?page=certificate&student=<?= $r['id'] ?>&year=<?= $year ?>&term=<?= $term ?>">Print certificate →</a></article><?php endforeach;?></div><section class="panel"><div class="panel-head"><div><h3>Class ranking</h3><p>Ranked by average of recorded end-of-term marks.</p></div><a class="btn secondary" href="index.php?page=certificates&class=<?= $cid ?>&year=<?= $year ?>&term=<?= $term ?>" target="_blank">Print top-three certificates</a></div><div class="table-wrap"><table><thead><tr><th>Position</th><th>Learner</th><th>Admission no.</th><th>Subjects marked</th><th>Average</th></tr></thead><tbody><?php foreach($ranking as $i=>$r):?><tr><td><span class="rank-pill">#<?= $i+1 ?></span></td><td><b><?= h($r['full_name']) ?></b></td><td><?= h($r['admission_no']) ?></td><td><?= (int)$r['subjects_count'] ?></td><td><b><?= $r['average']===null?'Not marked':number_format((float)$r['average'],1).'%'; ?></b></td></tr><?php endforeach;?></tbody></table></div></section>
<?php elseif($page==='certificate'||$page==='certificates'):$cid=(int)($_GET['class']??0);$sid=(int)($_GET['student']??0);$sql='SELECT s.*,c.name class_name,AVG(m.score) average FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN marks m ON m.student_id=s.id AND m.academic_year=? AND m.term=? AND m.assessment="EOT" WHERE s.status="Active"';$args=[$year,$term];if($sid){$sql.=' AND s.id=?';$args[]=$sid;}if($cid){$sql.=' AND s.class_id=?';$args[]=$cid;}$sql.=' GROUP BY s.id ORDER BY average DESC LIMIT '.($sid?'1':'3');$q=$pdo->prepare($sql);$q->execute($args);$winners=$q->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><title>Certificates</title><style>@page{size:A4 landscape;margin:12mm}body{font-family:Georgia,serif}.cert{height:175mm;border:12px double #236c63;margin:0 0 10mm;padding:15mm;text-align:center;box-sizing:border-box;page-break-after:always}.cert img{width:70px;height:70px;object-fit:contain}.cert h1{font-size:34px;color:#176879;margin:12px}.cert h2{font-size:28px;color:#aa873d}.cert p{font-size:18px}.cert .name{font-size:32px;border-bottom:1px solid #999;display:inline-block;padding:8px 30px}.cert .seal{margin-top:22px;color:#236c63;font-weight:bold}@media screen{body{background:#eee}.cert{background:#fff;max-width:1100px;margin:25px auto}}.no-print{text-align:center;padding:12px}@media print{.no-print{display:none}}</style></head><body><div class="no-print"><button onclick="print()">Print certificates</button></div><?php foreach($winners as $i=>$w):?><article class="cert"><img src="assets/school-logo.jpg" alt="School emblem"><h1><?= h(setting($pdo,'school_name',$school)) ?></h1><p>PROUDLY PRESENTS THIS CERTIFICATE OF</p><h2><?= $sid?'ACADEMIC ACHIEVEMENT':(['FIRST PLACE','SECOND PLACE','THIRD PLACE'][$i]??'ACADEMIC ACHIEVEMENT') ?></h2><p>Presented to</p><div class="name"><?= h($w['full_name']) ?></div><p>of <?= h($w['class_name']) ?> for outstanding academic performance in Term <?= $term ?>, <?= $year ?>.</p><p>Average score: <b><?= $w['average']===null?'—':number_format((float)$w['average'],1).'%' ?></b></p><div class="seal">THE GRACE OF GOD IS SUFFICIENT</div><p style="margin-top:30px">__________________________ &nbsp;&nbsp;&nbsp; __________________________</p><p>Class Teacher &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Head Teacher</p></article><?php endforeach;?></body></html><?php exit;?>
